-- F003 / WP92. Immutable directory cutover plans, atomic application and rollback.
-- Provider-neutral plans are generated by the application from a complete,
-- tenant-verified snapshot, then applied and rolled back by one transaction each.
-- Existing manual and other-provider rows are retained. Apply may create native
-- people with login disabled and no roles; directory sync never grants login.

begin;

-- Existing native triggers also run inside the directory RPC's empty search_path.
-- Keep their behavior while qualifying the table they operate on.
create or replace function public.update_department_path()
returns trigger language plpgsql set search_path = '' as $$
declare parent_path text;
begin
  if new.parent_id is null then
    new.path := '/' || new.id::text || '/';
    new.depth := 0;
  else
    select path, depth into parent_path, new.depth
      from public.departments where id = new.parent_id;
    new.path := parent_path || new.id::text || '/';
    new.depth := new.depth + 1;
  end if;
  return new;
end;
$$;
create or replace function public.update_dept_member_count()
returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    update public.departments set member_count = member_count + 1 where id = new.department_id;
  elsif tg_op = 'DELETE' then
    update public.departments set member_count = greatest(member_count - 1, 0) where id = old.department_id;
  end if;
  return null;
end;
$$;

alter table public.departments
  drop constraint if exists departments_source_check;
alter table public.departments
  add constraint departments_source_check
  check (source in ('manual', 'feishu', 'fxiaoke', 'dingtalk', 'wecom', 'csv'));

create unique index if not exists departments_org_source_external_unique
  on public.departments (org_id, source, external_id)
  where external_id is not null;

alter table public.user_departments
  add column if not exists source text not null default 'manual';
alter table public.user_departments
  drop constraint if exists user_departments_source_check;
alter table public.user_departments
  add constraint user_departments_source_check
  check (source in ('manual', 'feishu', 'fxiaoke', 'dingtalk', 'wecom', 'csv'));

create table if not exists public.organization_directory_cutover_plans (
  id uuid primary key default gen_random_uuid(),
  system_org_id uuid not null references public.organizations(id) on delete cascade,
  target_source_id uuid not null,
  connection_revision uuid not null,
  previous_primary_source_id uuid,
  directory_hash text not null check (directory_hash ~ '^[a-f0-9]{64}$'),
  plan_hash text not null check (plan_hash ~ '^[a-f0-9]{64}$'),
  plan_payload jsonb not null check (jsonb_typeof(plan_payload) = 'object'),
  status text not null default 'planned'
    check (status in ('planned', 'applied', 'superseded', 'rolled_back')),
  created_by uuid not null references public.users(id),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  applied_at timestamptz,
  rolled_back_at timestamptz,
  foreign key (target_source_id, system_org_id)
    references public.organization_sources(id, system_org_id)
    on delete restrict,
  foreign key (previous_primary_source_id, system_org_id)
    references public.organization_sources(id, system_org_id)
    on delete restrict,
  unique (system_org_id, plan_hash),
  check (expires_at > created_at),
  check (expires_at <= created_at + interval '1 hour'),
  check ((status in ('applied', 'rolled_back')) = (applied_at is not null)),
  check ((status = 'rolled_back') = (rolled_back_at is not null))
);

create index if not exists organization_directory_cutover_plans_latest
  on public.organization_directory_cutover_plans
    (system_org_id, target_source_id, created_at desc);
create index if not exists organization_directory_cutover_plans_active
  on public.organization_directory_cutover_plans
    (system_org_id, target_source_id, expires_at)
  where status = 'planned';

create table if not exists public.organization_directory_cutover_runs (
  id uuid primary key default gen_random_uuid(),
  system_org_id uuid not null references public.organizations(id) on delete cascade,
  plan_id uuid not null unique
    references public.organization_directory_cutover_plans(id) on delete restrict,
  target_source_id uuid not null,
  previous_primary_source_id uuid,
  status text not null default 'applied'
    check (status in ('applied', 'rolled_back')),
  department_count integer not null default 0 check (department_count >= 0),
  identity_count integer not null default 0 check (identity_count >= 0),
  member_count integer not null default 0 check (member_count >= 0),
  before_state jsonb not null check (jsonb_typeof(before_state) = 'object'),
  after_state jsonb not null check (jsonb_typeof(after_state) = 'object'),
  applied_by uuid not null references public.users(id),
  applied_at timestamptz not null default now(),
  rolled_back_by uuid references public.users(id),
  rolled_back_at timestamptz,
  foreign key (target_source_id, system_org_id)
    references public.organization_sources(id, system_org_id)
    on delete restrict,
  foreign key (previous_primary_source_id, system_org_id)
    references public.organization_sources(id, system_org_id)
    on delete restrict,
  check ((status = 'rolled_back') = (rolled_back_at is not null))
);

create index if not exists organization_directory_cutover_runs_latest
  on public.organization_directory_cutover_runs
    (system_org_id, applied_at desc);

alter table public.organization_directory_cutover_plans enable row level security;
alter table public.organization_directory_cutover_runs enable row level security;

revoke all on public.organization_directory_cutover_plans,
  public.organization_directory_cutover_runs
  from public, anon, authenticated;
grant select, insert, update on public.organization_directory_cutover_plans
  to service_role;
grant select, insert, update on public.organization_directory_cutover_runs
  to service_role;

create or replace function private.guard_directory_cutover_plan_v1()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.system_org_id is distinct from old.system_org_id
    or new.target_source_id is distinct from old.target_source_id
    or new.connection_revision is distinct from old.connection_revision
    or new.previous_primary_source_id is distinct from old.previous_primary_source_id
    or new.directory_hash is distinct from old.directory_hash
    or new.plan_hash is distinct from old.plan_hash
    or new.plan_payload is distinct from old.plan_payload
    or new.created_by is distinct from old.created_by
    or new.created_at is distinct from old.created_at
    or new.expires_at is distinct from old.expires_at then
    raise exception 'directory cutover plan identity is immutable'
      using errcode = '23514';
  end if;

  if new.status is distinct from old.status and not (
    (old.status = 'planned' and new.status in ('applied', 'superseded'))
    or (old.status = 'applied' and new.status = 'rolled_back')
  ) then
    raise exception 'invalid directory cutover plan status transition'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists organization_directory_cutover_plan_immutable
  on public.organization_directory_cutover_plans;
create trigger organization_directory_cutover_plan_immutable
before update on public.organization_directory_cutover_plans
for each row execute function private.guard_directory_cutover_plan_v1();

revoke all on function private.guard_directory_cutover_plan_v1()
  from public, anon, authenticated;

create unique index if not exists organization_sources_one_directory_authority
  on public.organization_sources(system_org_id)
  where authority_scope->>'directory' in ('authoritative', 'true');

create or replace function private.organization_directory_state_v1(
  p_system_org_id uuid,
  p_target_source_id uuid,
  p_user_ids uuid[]
) returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'sources', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', source.id,
        'systemOrgId', source.system_org_id,
        'provider', source.provider,
        'externalTenantId', source.external_tenant_id,
        'priority', source.priority,
        'status', source.status,
        'authorityScope', source.authority_scope,
        'syncMode', source.sync_mode,
        'configurationRevision', source.configuration_revision,
        'connectionState', source.connection_state,
        'effectiveRevision', source.effective_revision,
        'draftCheckStatus', source.draft_check_status,
        'lastSuccessfulSyncAt', case when source.last_successful_sync_at is null then null
          else to_char(source.last_successful_sync_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,
        'lastError', source.last_error,
        'lastErrorAt', case when source.last_error_at is null then null
          else to_char(source.last_error_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,
        'updatedAt', to_char(source.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      ) order by source.id)
      from public.organization_sources as source
      where source.system_org_id = p_system_org_id
    ), '[]'::jsonb),
    'targetDepartments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', department.id,
        'orgId', department.org_id,
        'parentId', department.parent_id,
        'name', department.name,
        'code', department.code,
        'path', department.path,
        'depth', department.depth,
        'externalId', department.external_id,
        'source', department.source,
        'status', department.status,
        'sortOrder', department.sort_order,
        'memberCount', department.member_count,
        'updatedAt', to_char(department.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      ) order by department.id)
      from public.departments as department
      where department.org_id = p_system_org_id
        and department.source = (
          select target.provider
            from public.organization_sources as target
           where target.id = p_target_source_id
             and target.system_org_id = p_system_org_id
        )
    ), '[]'::jsonb),
    'targetIdentities', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', identity.id,
        'sourceId', identity.source_id,
        'systemOrgId', identity.system_org_id,
        'externalUserId', identity.external_user_id,
        'externalUnionId', identity.external_union_id,
        'externalOpenId', identity.external_open_id,
        'canonicalUserId', identity.canonical_user_id,
        'matchStatus', identity.match_status,
        'matchMethod', identity.match_method,
        'matchConfidence', identity.match_confidence,
        'profileSnapshot', identity.profile_snapshot,
        'observedAt', to_char(identity.observed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'updatedAt', to_char(identity.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      ) order by identity.id)
      from public.external_identities as identity
      where identity.system_org_id = p_system_org_id
        and identity.source_id = p_target_source_id
    ), '[]'::jsonb),
    'users', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', user_row.id,
        'primaryDepartmentId', user_row.primary_dept_id,
        'status', user_row.status,
        'loginEnabled', user_row.login_enabled,
        'updatedAt', to_char(user_row.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      ) order by user_row.id)
      from public.users as user_row
      where user_row.org_id = p_system_org_id
        and user_row.id = any(p_user_ids)
    ), '[]'::jsonb),
    'organizationMemberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId', membership.user_id, 'orgId', membership.org_id,
        'primaryDepartmentId', membership.primary_department_id,
        'status', membership.status, 'employmentStatus', membership.employment_status,
        'isDefault', membership.is_default,
        'createdAt', to_char(membership.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      ) order by membership.user_id)
      from public.user_organizations membership
      where membership.org_id = p_system_org_id and membership.user_id = any(p_user_ids)
    ), '[]'::jsonb),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId', membership.user_id,
        'departmentId', membership.department_id,
        'orgId', membership.org_id,
        'isPrimary', membership.is_primary,
        'source', membership.source,
        'joinedAt', to_char(membership.joined_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      ) order by membership.user_id, membership.department_id)
      from public.user_departments as membership
      where membership.org_id = p_system_org_id
        and membership.user_id = any(p_user_ids)
    ), '[]'::jsonb)
  );
$$;

create or replace function private.organization_directory_state_matches_v1(
  p_system_org_id uuid,
  p_target_source_id uuid,
  p_state jsonb
) returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_user_ids uuid[];
  v_count integer;
  v_source_count integer;
  v_department_count integer;
  v_identity_count integer;
  v_user_count integer;
  v_membership_count integer;
  v_target_provider text;
begin
  if p_state is null or jsonb_typeof(p_state) <> 'object' then return false; end if;
  if jsonb_typeof(p_state->'sources') <> 'array'
    or jsonb_typeof(p_state->'targetDepartments') <> 'array'
    or jsonb_typeof(p_state->'targetIdentities') <> 'array'
    or jsonb_typeof(p_state->'users') <> 'array'
    or jsonb_typeof(p_state->'memberships') <> 'array'
    or jsonb_typeof(p_state->'organizationMemberships') is distinct from 'array' then return false; end if;

  select source.provider into v_target_provider
    from public.organization_sources as source
   where source.id = p_target_source_id and source.system_org_id = p_system_org_id;
  if v_target_provider is null then return false; end if;

  select coalesce(array_agg((user_item->>'id')::uuid), array[]::uuid[])
    into v_user_ids
    from jsonb_array_elements(p_state->'users') as user_item;

  select count(*)::integer into v_source_count
    from public.organization_sources where system_org_id = p_system_org_id;
  if v_source_count <> jsonb_array_length(p_state->'sources') then return false; end if;
  for v_item in select value from jsonb_array_elements(p_state->'sources') loop
    if not exists (
      select 1
        from public.organization_sources as source
       where source.id = (v_item->>'id')::uuid
         and source.system_org_id = p_system_org_id
         and source.system_org_id = (v_item->>'systemOrgId')::uuid
         and source.provider = v_item->>'provider'
         and source.external_tenant_id = v_item->>'externalTenantId'
         and source.priority = (v_item->>'priority')::integer
         and source.status = v_item->>'status'
         and source.authority_scope = coalesce(v_item->'authorityScope', '{}'::jsonb)
         and source.sync_mode = v_item->>'syncMode'
         and source.configuration_revision = (v_item->>'configurationRevision')::uuid
         and source.connection_state = v_item->>'connectionState'
         and source.effective_revision is not distinct from nullif(v_item->>'effectiveRevision', '')::uuid
         and source.draft_check_status = v_item->>'draftCheckStatus'
         and source.last_successful_sync_at is not distinct from nullif(v_item->>'lastSuccessfulSyncAt', '')::timestamptz
         and source.last_error is not distinct from nullif(v_item->>'lastError', '')
         and source.last_error_at is not distinct from nullif(v_item->>'lastErrorAt', '')::timestamptz
         and source.updated_at = (v_item->>'updatedAt')::timestamptz
    ) then return false; end if;
  end loop;

  select count(*)::integer into v_department_count
    from public.departments
   where org_id = p_system_org_id and source = v_target_provider;
  if v_department_count <> jsonb_array_length(p_state->'targetDepartments') then return false; end if;
  for v_item in select value from jsonb_array_elements(p_state->'targetDepartments') loop
    if not exists (
      select 1
        from public.departments as department
       where department.id = (v_item->>'id')::uuid
         and department.org_id = p_system_org_id
         and department.org_id = (v_item->>'orgId')::uuid
         and department.parent_id is not distinct from nullif(v_item->>'parentId', '')::uuid
         and department.name = v_item->>'name'
         and department.code is not distinct from nullif(v_item->>'code', '')
         and department.path is not distinct from nullif(v_item->>'path', '')
         and department.depth = (v_item->>'depth')::integer
         and department.external_id is not distinct from nullif(v_item->>'externalId', '')
         and department.source = v_item->>'source'
         and department.status = v_item->>'status'
         and department.sort_order = (v_item->>'sortOrder')::integer
         and department.member_count = (v_item->>'memberCount')::integer
         and department.updated_at = (v_item->>'updatedAt')::timestamptz
    ) then return false; end if;
  end loop;

  select count(*)::integer into v_identity_count
    from public.external_identities
   where system_org_id = p_system_org_id and source_id = p_target_source_id;
  if v_identity_count <> jsonb_array_length(p_state->'targetIdentities') then return false; end if;
  for v_item in select value from jsonb_array_elements(p_state->'targetIdentities') loop
    if not exists (
      select 1
        from public.external_identities as identity
       where identity.id = (v_item->>'id')::uuid
         and identity.source_id = p_target_source_id
         and identity.system_org_id = p_system_org_id
         and identity.system_org_id = (v_item->>'systemOrgId')::uuid
         and identity.external_user_id = v_item->>'externalUserId'
         and identity.external_union_id is not distinct from nullif(v_item->>'externalUnionId', '')
         and identity.external_open_id is not distinct from nullif(v_item->>'externalOpenId', '')
         and identity.canonical_user_id is not distinct from nullif(v_item->>'canonicalUserId', '')::uuid
         and identity.match_status = v_item->>'matchStatus'
         and identity.match_method = v_item->>'matchMethod'
         and identity.match_confidence = (v_item->>'matchConfidence')::numeric
         and identity.profile_snapshot = v_item->'profileSnapshot'
         and identity.observed_at = (v_item->>'observedAt')::timestamptz
         and identity.updated_at = (v_item->>'updatedAt')::timestamptz
    ) then return false; end if;
  end loop;

  select count(*)::integer into v_user_count
    from public.users
   where org_id = p_system_org_id and id = any(v_user_ids);
  if v_user_count <> jsonb_array_length(p_state->'users') then return false; end if;
  for v_item in select value from jsonb_array_elements(p_state->'users') loop
    if not exists (
      select 1
        from public.users as user_row
       where user_row.id = (v_item->>'id')::uuid
         and user_row.org_id = p_system_org_id
         and user_row.primary_dept_id is not distinct from nullif(v_item->>'primaryDepartmentId', '')::uuid
         and user_row.status is not distinct from nullif(v_item->>'status', '')
         and user_row.login_enabled = (v_item->>'loginEnabled')::boolean
         and user_row.updated_at = (v_item->>'updatedAt')::timestamptz
    ) then return false; end if;
  end loop;

  select count(*)::integer into v_count from public.user_organizations
   where org_id = p_system_org_id and user_id = any(v_user_ids);
  if v_count <> jsonb_array_length(p_state->'organizationMemberships') then return false; end if;
  for v_item in select value from jsonb_array_elements(p_state->'organizationMemberships') loop
    if not exists (
      select 1 from public.user_organizations membership
       where membership.org_id = p_system_org_id and membership.user_id = (v_item->>'userId')::uuid
         and membership.primary_department_id is not distinct from nullif(v_item->>'primaryDepartmentId', '')::uuid
         and membership.status = v_item->>'status' and membership.employment_status = v_item->>'employmentStatus'
         and membership.is_default = (v_item->>'isDefault')::boolean
         and membership.created_at = (v_item->>'createdAt')::timestamptz
    ) then return false; end if;
  end loop;

  select count(*)::integer into v_membership_count
    from public.user_departments
   where org_id = p_system_org_id and user_id = any(v_user_ids);
  if v_membership_count <> jsonb_array_length(p_state->'memberships') then return false; end if;
  for v_item in select value from jsonb_array_elements(p_state->'memberships') loop
    if not exists (
      select 1
        from public.user_departments as membership
       where membership.user_id = (v_item->>'userId')::uuid
         and membership.department_id = (v_item->>'departmentId')::uuid
         and membership.org_id = p_system_org_id
         and membership.org_id = (v_item->>'orgId')::uuid
         and membership.is_primary = (v_item->>'isPrimary')::boolean
         and membership.source = coalesce(v_item->>'source', 'manual')
         and membership.joined_at = (v_item->>'joinedAt')::timestamptz
    ) then return false; end if;
  end loop;

  select count(*)::integer into v_count
    from public.external_identities
   where system_org_id = p_system_org_id and source_id = p_target_source_id;
  return v_count = v_identity_count;
end;
$$;

create or replace function private.organization_source_revisions_match_v1(
  p_system_org_id uuid,
  p_revisions jsonb
) returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_current_count integer;
  v_expected_count integer;
begin
  if p_revisions is null or jsonb_typeof(p_revisions) <> 'array' then return false; end if;
  v_expected_count := jsonb_array_length(p_revisions);
  select count(*)::integer into v_current_count
    from public.organization_sources where system_org_id = p_system_org_id;
  if v_current_count <> v_expected_count then return false; end if;
  if (
    select count(distinct item->>'id')
      from jsonb_array_elements(p_revisions) as item
  ) <> v_expected_count then return false; end if;

  for v_item in select value from jsonb_array_elements(p_revisions) loop
    if not exists (
      select 1
        from public.organization_sources as source
       where source.id = (v_item->>'id')::uuid
         and source.system_org_id = p_system_org_id
         and source.provider = v_item->>'provider'
         and source.priority = (v_item->>'priority')::integer
         and source.status = v_item->>'status'
         and source.sync_mode = v_item->>'syncMode'
         and source.configuration_revision = (v_item->>'configurationRevision')::uuid
         and source.updated_at = (v_item->>'updatedAt')::timestamptz
    ) then return false; end if;
  end loop;
  return true;
end;
$$;

create or replace function public.store_organization_directory_cutover_plan_v1(
  p_system_org_id uuid,
  p_target_source_id uuid,
  p_connection_revision uuid,
  p_previous_primary_source_id uuid,
  p_directory_hash text,
  p_plan_hash text,
  p_plan_payload jsonb,
  p_actor_id uuid,
  p_expires_at timestamptz
) returns setof public.organization_directory_cutover_plans
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_source public.organization_sources%rowtype;
begin
  if p_system_org_id is null or p_target_source_id is null
    or p_connection_revision is null or p_actor_id is null or p_expires_at is null
    or p_directory_hash is null or p_directory_hash !~ '^[a-f0-9]{64}$'
    or p_plan_hash is null or p_plan_hash !~ '^[a-f0-9]{64}$'
    or p_plan_payload is null or jsonb_typeof(p_plan_payload) <> 'object'
    or p_expires_at <= now() or p_expires_at > now() + interval '1 hour' then
    raise exception 'invalid directory cutover plan input' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.users where id = p_actor_id and org_id = p_system_org_id
  ) then
    raise exception 'directory cutover plan actor is outside the organization'
      using errcode = '23514';
  end if;
  if p_plan_payload->>'version' <> 'f003-directory-cutover-v2'
    or p_plan_payload->>'organizationId' <> p_system_org_id::text
    or p_plan_payload->>'targetSourceId' <> p_target_source_id::text
    or p_plan_payload->>'connectionRevision' <> p_connection_revision::text
    or p_plan_payload->>'planHash' <> lower(p_plan_hash)
    or p_plan_payload->'snapshot'->>'directoryHash' <> lower(p_directory_hash)
    or p_plan_payload->>'previousPrimarySourceId' is distinct from p_previous_primary_source_id::text then
    raise exception 'directory cutover plan payload identity mismatch'
      using errcode = '23514';
  end if;

  select * into v_source
    from public.organization_sources
   where id = p_target_source_id and system_org_id = p_system_org_id
   for update;
  if not found
    or p_plan_payload->>'targetProvider' <> v_source.provider
    or v_source.provider not in ('feishu', 'fxiaoke', 'wecom', 'dingtalk')
    or v_source.configuration_revision <> p_connection_revision then
    raise exception 'directory cutover target source is stale or missing'
      using errcode = '40001';
  end if;

  update public.organization_directory_cutover_plans
     set status = 'superseded'
   where system_org_id = p_system_org_id
     and target_source_id = p_target_source_id
     and status = 'planned';

  return query
  insert into public.organization_directory_cutover_plans(
    system_org_id, target_source_id, connection_revision,
    previous_primary_source_id, directory_hash, plan_hash, plan_payload,
    status, created_by, created_at, expires_at
  ) values (
    p_system_org_id, p_target_source_id, p_connection_revision,
    p_previous_primary_source_id, lower(p_directory_hash), lower(p_plan_hash),
    p_plan_payload, 'planned', p_actor_id, now(), p_expires_at
  )
  returning *;
end;
$$;

create or replace function public.apply_organization_directory_cutover_v1(
  p_system_org_id uuid,
  p_plan_id uuid,
  p_plan_hash text,
  p_connection_revision uuid,
  p_source_revisions jsonb,
  p_actor_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_plan public.organization_directory_cutover_plans%rowtype;
  v_run public.organization_directory_cutover_runs%rowtype;
  v_payload jsonb;
  v_before_state jsonb;
  v_after_state jsonb;
  v_change jsonb;
  v_item jsonb;
  v_kind text;
  v_external_id text;
  v_department_id uuid;
  v_parent_id uuid;
  v_primary_department_id uuid;
  v_department_ids uuid[];
  v_department_external_ids text[];
  v_user_id uuid;
  v_identity_id uuid;
  v_affected_user_ids uuid[];
  v_department_map jsonb := '{}'::jsonb;
  v_now timestamptz := now();
  v_ordinality bigint;
  v_department_count integer := 0;
  v_identity_count integer := 0;
  v_target_provider text;
begin
  if p_system_org_id is null or p_plan_id is null or p_actor_id is null
    or p_connection_revision is null
    or p_plan_hash is null or p_plan_hash !~ '^[a-f0-9]{64}$'
    or p_source_revisions is null or jsonb_typeof(p_source_revisions) <> 'array' then
    raise exception 'invalid directory cutover input' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.users
     where id = p_actor_id and org_id = p_system_org_id
  ) then
    raise exception 'directory cutover actor is outside the organization'
      using errcode = '23514';
  end if;

  select * into v_plan
    from public.organization_directory_cutover_plans
   where id = p_plan_id and system_org_id = p_system_org_id
   for update;
  if not found then raise exception 'directory cutover plan not found' using errcode = 'P0002'; end if;

  if v_plan.plan_hash <> lower(p_plan_hash) then
    raise exception 'directory cutover plan hash mismatch' using errcode = '23514';
  end if;
  if v_plan.status = 'applied' then
    select * into v_run from public.organization_directory_cutover_runs
     where plan_id = v_plan.id and system_org_id = p_system_org_id;
    if not found then raise exception 'applied directory cutover run is missing' using errcode = '23514'; end if;
    return jsonb_build_object(
      'id', v_run.id, 'plan_id', v_run.plan_id, 'status', v_run.status,
      'target_source_id', v_run.target_source_id,
      'previous_primary_source_id', v_run.previous_primary_source_id,
      'department_count', v_run.department_count,
      'identity_count', v_run.identity_count,
      'member_count', v_run.member_count,
      'applied_at', v_run.applied_at, 'rolled_back_at', v_run.rolled_back_at
    );
  end if;
  if v_plan.status <> 'planned' then
    raise exception 'directory cutover plan is not applyable because it is %', v_plan.status
      using errcode = '23514';
  end if;
  if v_plan.expires_at <= v_now then
    raise exception 'directory cutover plan expired' using errcode = '23514';
  end if;

  select source.provider into v_target_provider
    from public.organization_sources as source
   where source.id = v_plan.target_source_id
     and source.system_org_id = p_system_org_id;
  if v_target_provider is null then
    raise exception 'directory cutover target source is missing' using errcode = '23514';
  end if;

  v_payload := v_plan.plan_payload;
  v_before_state := v_payload->'beforeState';
  if coalesce((v_payload->>'applyable')::boolean, false) is not true
    or v_payload->'conflicts' is distinct from '[]'::jsonb
    or coalesce((v_payload->'snapshot'->>'complete')::boolean, false) is not true
    or coalesce((v_payload->'snapshot'->>'connectionVerified')::boolean, false) is not true then
    raise exception 'directory cutover plan is not applyable because conflicts or incomplete snapshot remain'
      using errcode = '23514';
  end if;
  if v_payload->>'version' <> 'f003-directory-cutover-v2'
    or v_payload->>'targetProvider' <> v_target_provider
    or (v_payload->>'targetSourceId')::uuid <> v_plan.target_source_id
    or (v_payload->>'connectionRevision')::uuid <> p_connection_revision
    or v_plan.connection_revision <> p_connection_revision then
    raise exception 'directory cutover plan target or connection revision mismatch'
      using errcode = '23514';
  end if;
  if jsonb_typeof(v_payload->'departmentChanges') <> 'array'
    or jsonb_typeof(v_payload->'identityChanges') <> 'array'
    or jsonb_typeof(v_payload->'userDepartmentChanges') <> 'array'
    or jsonb_typeof(v_before_state) <> 'object' then
    raise exception 'directory cutover plan payload is malformed'
      using errcode = '23514';
  end if;

  perform 1 from public.organization_sources
   where system_org_id = p_system_org_id order by id for update;
  if not exists (
    select 1 from public.organization_sources
     where id = v_plan.target_source_id
       and system_org_id = p_system_org_id
       and provider = v_target_provider
       and configuration_revision = p_connection_revision
  ) then
    raise exception 'directory target connection is no longer effective'
      using errcode = '23514';
  end if;
  perform 1 from public.departments where org_id = p_system_org_id and source = v_target_provider order by id for update;
  perform 1 from public.users where org_id = p_system_org_id and id in (
    select (item->>'userId')::uuid from jsonb_array_elements(v_payload->'userDepartmentChanges') item
  ) order by id for update;
  perform 1 from public.user_organizations where org_id = p_system_org_id order by user_id for update;
  perform 1 from public.user_departments where org_id = p_system_org_id order by user_id, department_id for update;
  perform 1 from public.external_identities where system_org_id = p_system_org_id and source_id = v_plan.target_source_id order by id for update;
  if not private.organization_source_revisions_match_v1(p_system_org_id, p_source_revisions)
    or p_source_revisions is distinct from v_payload->'sourceRevisions'
    or not private.organization_directory_state_matches_v1(
      p_system_org_id, v_plan.target_source_id, v_before_state
    ) then
    raise exception 'directory or source state changed after plan preview'
      using errcode = '40001';
  end if;

  select coalesce(array_agg((item->>'userId')::uuid order by item->>'userId'), array[]::uuid[])
    into v_affected_user_ids
    from jsonb_array_elements(v_payload->'userDepartmentChanges') as item;

  if v_plan.previous_primary_source_id is not null
    and v_plan.previous_primary_source_id <> v_plan.target_source_id then
    update public.organization_sources
       set authority_scope = authority_scope || jsonb_build_object('directory', 'retained', 'organization', 'evidence'),
           updated_at = v_now
     where id = v_plan.previous_primary_source_id
       and system_org_id = p_system_org_id;
  end if;
  update public.organization_sources
     set authority_scope = authority_scope || jsonb_build_object(
           'directory', 'authoritative',
           'organization', 'authoritative'
         ),
         last_successful_sync_at = v_now,
         last_error = null,
         last_error_at = null,
         updated_at = v_now
   where id = v_plan.target_source_id
     and system_org_id = p_system_org_id;

  select coalesce(jsonb_object_agg(external_id, id::text), '{}'::jsonb)
    into v_department_map
    from public.departments
   where org_id = p_system_org_id
     and source = v_target_provider
     and external_id is not null;

  for v_change, v_ordinality in
    select value, ordinality
      from jsonb_array_elements(v_payload->'departmentChanges') with ordinality
  loop
    v_kind := v_change->>'kind';
    v_external_id := v_change->>'externalId';
    v_department_id := nullif(v_change->>'existingDepartmentId', '')::uuid;
    if v_external_id is null or v_kind not in ('added', 'updated', 'unchanged') then
      raise exception 'directory department change is malformed' using errcode = '23514';
    end if;
    if v_kind = 'added' then
      if v_department_map ? v_external_id then
        raise exception 'directory state changed: added department already exists' using errcode = '40001';
      end if;
      v_department_id := gen_random_uuid();
      v_parent_id := case when nullif(v_change->>'parentExternalId', '') is null then null
        else nullif(v_department_map->>(v_change->>'parentExternalId'), '')::uuid end;
      insert into public.departments(
        id, org_id, parent_id, name, external_id, source, status, sort_order,
        member_count, created_at, updated_at
      ) values (
        v_department_id, p_system_org_id, v_parent_id,
        v_change->>'name', v_external_id, v_target_provider,
        case when v_change->>'status' = 'inactive' then 'inactive' else 'active' end,
        v_ordinality::integer - 1, 0, v_now, v_now
      );
      v_department_map := jsonb_set(v_department_map, array[v_external_id], to_jsonb(v_department_id::text), true);
    else
      if v_department_id is null
        or nullif(v_department_map->>v_external_id, '')::uuid is distinct from v_department_id then
        raise exception 'directory state changed: existing department identity mismatch' using errcode = '40001';
      end if;
    end if;
    v_parent_id := case when nullif(v_change->>'parentExternalId', '') is null then null
      else nullif(v_department_map->>(v_change->>'parentExternalId'), '')::uuid end;
    if nullif(v_change->>'parentExternalId', '') is not null and v_parent_id is null then
      raise exception 'directory state changed: parent department is missing' using errcode = '40001';
    end if;
    update public.departments
       set parent_id = v_parent_id,
           name = v_change->>'name',
           status = case when v_change->>'status' = 'inactive' then 'inactive' else 'active' end,
           sort_order = v_ordinality::integer - 1,
           updated_at = v_now
     where id = v_department_id
       and org_id = p_system_org_id
       and source = v_target_provider;
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_payload->'staleTargetDepartmentIds', '[]'::jsonb)) loop
    update public.departments
       set status = 'inactive', updated_at = v_now
     where id = (v_item#>>'{}')::uuid
       and org_id = p_system_org_id
       and source = v_target_provider;
  end loop;

  with recursive tree as (
    select department.id,
           ('/' || department.id::text || '/')::text as next_path,
           0 as next_depth
      from public.departments as department
     where department.org_id = p_system_org_id
       and department.source = v_target_provider
       and department.parent_id is null
    union all
    select child.id,
           (tree.next_path || child.id::text || '/')::text,
           tree.next_depth + 1
      from public.departments as child
      join tree on child.parent_id = tree.id
     where child.org_id = p_system_org_id
       and child.source = v_target_provider
  )
  update public.departments as department
     set path = tree.next_path,
         depth = tree.next_depth
    from tree
   where department.id = tree.id;

  for v_change in select value from jsonb_array_elements(v_payload->'identityChanges') loop
    v_kind := v_change->>'kind';
    v_external_id := v_change->>'externalUserId';
    v_user_id := nullif(v_change->>'canonicalUserId', '')::uuid;
    v_identity_id := nullif(v_change->>'existingIdentityId', '')::uuid;
    if v_kind not in ('added', 'updated', 'unchanged') or v_user_id is null then
      raise exception 'directory identity must resolve to a real organization member' using errcode = '23514';
    end if;
    if coalesce((v_change->>'createsMember')::boolean, false) then
      if exists (select 1 from public.users where id = v_user_id)
        or v_change->>'matchMethod' <> 'none'
        or v_change->'profileSnapshot'->>'provisionedMemberId' is distinct from v_user_id::text then
        raise exception 'directory member creation is stale or inconsistent' using errcode = '40001';
      end if;
      -- A person record is not a login grant. Do not create credentials, invitations, sessions or roles.
      insert into public.users(id, org_id, display_name, status, login_enabled, created_at, updated_at)
        values (v_user_id, p_system_org_id, v_change->>'displayName', 'inactive', false, v_now, v_now);
    elsif not exists (select 1 from public.users where id = v_user_id and org_id = p_system_org_id) then
      raise exception 'directory member is outside the organization' using errcode = '23514';
    end if;
    if coalesce(v_external_id, '') = ''
      or jsonb_typeof(v_change->'departmentExternalIds') is distinct from 'array'
      or jsonb_array_length(v_change->'departmentExternalIds') = 0
      or not coalesce((v_department_map ? (v_change->'profileSnapshot'->>'primaryDepartmentExternalId')), false)
      or not coalesce(((v_change->'departmentExternalIds') ? (v_change->'profileSnapshot'->>'primaryDepartmentExternalId')), false)
      or not ((v_change->'departmentExternalIds') @> (v_change->'profileSnapshot'->'departmentExternalIds')
        and (v_change->'departmentExternalIds') <@ (v_change->'profileSnapshot'->'departmentExternalIds'))
      or exists (
        select 1 from jsonb_array_elements_text(v_change->'departmentExternalIds') as link(external_id)
        where not (v_department_map ? link.external_id)
      )
 then
      raise exception 'directory employee or department relationship is malformed' using errcode = '23514';
    end if;
    if v_identity_id is null then
      if v_kind <> 'added' then
        raise exception 'directory state changed: existing identity is missing' using errcode = '40001';
      end if;
      insert into public.external_identities(
        source_id, system_org_id, external_user_id, canonical_user_id,
        match_status, match_method, match_confidence, profile_snapshot,
        observed_at, updated_at
      ) values (
        v_plan.target_source_id, p_system_org_id, v_external_id, v_user_id,
        'matched', v_change->>'matchMethod', (v_change->>'confidence')::numeric,
        coalesce(v_change->'profileSnapshot', '{}'::jsonb), v_now, v_now
      );
    else
      update public.external_identities
         set canonical_user_id = v_user_id,
             match_status = 'matched',
             match_method = v_change->>'matchMethod',
             match_confidence = (v_change->>'confidence')::numeric,
             profile_snapshot = coalesce(v_change->'profileSnapshot', '{}'::jsonb),
             observed_at = v_now,
             updated_at = v_now
       where id = v_identity_id
         and source_id = v_plan.target_source_id
         and system_org_id = p_system_org_id
         and external_user_id = v_external_id;
      if not found then
        raise exception 'directory state changed: identity identity mismatch' using errcode = '40001';
      end if;
    end if;
  end loop;

  for v_change in select value from jsonb_array_elements(v_payload->'userDepartmentChanges') loop
    v_user_id := (v_change->>'userId')::uuid;
    if not exists (select 1 from public.users where id = v_user_id and org_id = p_system_org_id) then
      raise exception 'directory membership target user is outside the organization' using errcode = '23514';
    end if;
    select coalesce(array_agg((department_item#>>'{}')::text order by department_item#>>'{}'), array[]::text[]),
           coalesce(array_agg(nullif(v_department_map->>(department_item#>>'{}'), '')::uuid order by department_item#>>'{}'), array[]::uuid[])
      into v_department_external_ids, v_department_ids
      from jsonb_array_elements(coalesce(v_change->'departmentExternalIds', '[]'::jsonb)) as department_item;
    if cardinality(v_department_ids) = 0 or array_position(v_department_ids, null) is not null then
      raise exception 'directory membership references an unknown department' using errcode = '40001';
    end if;
    v_primary_department_id := nullif(v_department_map->>(v_change->>'primaryDepartmentExternalId'), '')::uuid;

    -- The native department relationship has a composite FK to this membership.
    insert into public.user_organizations(membership_id, user_id, org_id, is_default, status, employment_status, primary_department_id)
      select gen_random_uuid(), v_user_id, p_system_org_id, true,
        case when user_row.login_enabled = false and user_row.status = 'inactive' then 'invited' else 'active' end,
        case when (v_change->>'active')::boolean then 'active' else 'suspended' end,
        v_primary_department_id
      from public.users user_row where user_row.id = v_user_id and user_row.org_id = p_system_org_id
      on conflict (user_id, org_id) do update set primary_department_id = excluded.primary_department_id,
        employment_status = excluded.employment_status;

    delete from public.user_departments as membership
     using public.departments as department
     where membership.user_id = v_user_id
       and membership.org_id = p_system_org_id
       and membership.source = v_target_provider
       and department.id = membership.department_id
       and department.org_id = p_system_org_id
       and department.source = v_target_provider
       and department.external_id is not null
       and not (department.external_id = any(v_department_external_ids));

    update public.user_departments
       set is_primary = false
     where user_id = v_user_id and org_id = p_system_org_id;

    foreach v_department_id in array v_department_ids loop
      insert into public.user_departments(
        user_id, department_id, is_primary, joined_at, org_id, source
      ) values (
        v_user_id, v_department_id,
        v_department_id = v_primary_department_id,
        v_now, p_system_org_id, v_target_provider
      )
      on conflict (user_id, department_id)
      do update set is_primary = excluded.is_primary;
    end loop;

    update public.users as user_row
       set primary_dept_id = v_primary_department_id,
           updated_at = v_now
     where user_row.id = v_user_id
       and user_row.org_id = p_system_org_id;
  end loop;

  update public.departments as department
     set member_count = (
       select count(*)::integer from public.user_departments membership
        where membership.department_id = department.id and membership.org_id = p_system_org_id
     )
   where department.org_id = p_system_org_id
     and department.source = v_target_provider;

  select count(*)::integer into v_department_count
    from public.departments where org_id = p_system_org_id and source = v_target_provider;
  select count(*)::integer into v_identity_count
    from public.external_identities
   where system_org_id = p_system_org_id and source_id = v_plan.target_source_id;

  v_after_state := private.organization_directory_state_v1(
    p_system_org_id, v_plan.target_source_id, v_affected_user_ids
  );
  insert into public.organization_directory_cutover_runs(
    system_org_id, plan_id, target_source_id, previous_primary_source_id,
    status, department_count, identity_count, member_count,
    before_state, after_state, applied_by, applied_at
  ) values (
    p_system_org_id, v_plan.id, v_plan.target_source_id, v_plan.previous_primary_source_id,
    'applied', v_department_count, v_identity_count, cardinality(v_affected_user_ids),
    v_before_state, v_after_state, p_actor_id, v_now
  ) returning * into v_run;

  update public.organization_directory_cutover_plans
     set status = 'applied', applied_at = v_now
   where id = v_plan.id;

  return jsonb_build_object(
    'id', v_run.id, 'plan_id', v_run.plan_id, 'status', v_run.status,
    'target_source_id', v_run.target_source_id,
    'previous_primary_source_id', v_run.previous_primary_source_id,
    'department_count', v_run.department_count,
    'identity_count', v_run.identity_count,
    'member_count', v_run.member_count,
    'applied_at', v_run.applied_at, 'rolled_back_at', v_run.rolled_back_at
  );
end;
$$;

create or replace function public.rollback_organization_directory_cutover_v1(
  p_system_org_id uuid,
  p_plan_id uuid,
  p_actor_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_plan public.organization_directory_cutover_plans%rowtype;
  v_run public.organization_directory_cutover_runs%rowtype;
  v_before_state jsonb;
  v_after_state jsonb;
  v_item jsonb;
  v_user_id uuid;
  v_user_ids uuid[];
  v_created_user_ids uuid[];
  v_reference record;
  v_has_reference boolean;
  v_before_department_ids uuid[];
  v_before_identity_ids uuid[];
  v_target_provider text;
  v_now timestamptz := now();
begin
  if p_system_org_id is null or p_plan_id is null or p_actor_id is null then
    raise exception 'invalid directory rollback input' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.users where id = p_actor_id and org_id = p_system_org_id
  ) then
    raise exception 'directory rollback actor is outside the organization'
      using errcode = '23514';
  end if;

  select * into v_plan
    from public.organization_directory_cutover_plans
   where id = p_plan_id and system_org_id = p_system_org_id
   for update;
  if not found then raise exception 'directory cutover plan not found' using errcode = 'P0002'; end if;
  select source.provider into v_target_provider
    from public.organization_sources as source
   where source.id = v_plan.target_source_id
     and source.system_org_id = p_system_org_id;
  if v_target_provider is null
    or v_plan.plan_payload->>'targetProvider' is distinct from v_target_provider then
    raise exception 'directory rollback target provider is missing or inconsistent'
      using errcode = '23514';
  end if;
  select * into v_run
    from public.organization_directory_cutover_runs
   where plan_id = v_plan.id and system_org_id = p_system_org_id
   for update;
  if not found then raise exception 'directory cutover run not found' using errcode = 'P0002'; end if;
  if v_run.status = 'rolled_back' then
    return jsonb_build_object(
      'id', v_run.id, 'plan_id', v_run.plan_id, 'status', v_run.status,
      'target_source_id', v_run.target_source_id,
      'previous_primary_source_id', v_run.previous_primary_source_id,
      'department_count', v_run.department_count,
      'identity_count', v_run.identity_count,
      'member_count', v_run.member_count,
      'applied_at', v_run.applied_at, 'rolled_back_at', v_run.rolled_back_at
    );
  end if;
  if v_plan.status <> 'applied' or v_run.status <> 'applied' then
    raise exception 'directory cutover plan is not applyable for rollback'
      using errcode = '23514';
  end if;

  perform 1 from public.organization_sources
   where system_org_id = p_system_org_id order by id for update;
  v_before_state := v_plan.plan_payload->'beforeState';
  v_after_state := v_run.after_state;
  perform 1 from public.users where org_id = p_system_org_id
    and id in (select (item->>'id')::uuid from jsonb_array_elements(v_after_state->'users') item)
    order by id for update;
  if not private.organization_directory_state_matches_v1(
    p_system_org_id, v_plan.target_source_id, v_after_state
  ) then
    raise exception 'directory or source state changed after cutover; rollback rejected'
      using errcode = '40001';
  end if;

  select coalesce(array_agg((item->>'userId')::uuid), array[]::uuid[]) into v_user_ids
    from jsonb_array_elements(v_plan.plan_payload->'userDepartmentChanges') item;
  select coalesce(array_agg((item->>'canonicalUserId')::uuid), array[]::uuid[]) into v_created_user_ids
    from jsonb_array_elements(v_plan.plan_payload->'identityChanges') item
    where coalesce((item->>'createsMember')::boolean, false);

  -- A provisioned person may have acquired business references since sync. Never cascade-delete those.
  for v_reference in
    select namespace.nspname as schema_name, relation.relname as table_name, attribute.attname as column_name
    from pg_catalog.pg_constraint constraint_row
    join pg_catalog.pg_class relation on relation.oid = constraint_row.conrelid
    join pg_catalog.pg_namespace namespace on namespace.oid = relation.relnamespace
    join lateral unnest(constraint_row.conkey, constraint_row.confkey) as keys(local_key, foreign_key) on true
    join pg_catalog.pg_attribute attribute on attribute.attrelid = relation.oid and attribute.attnum = keys.local_key
    join pg_catalog.pg_attribute target_attribute on target_attribute.attrelid = constraint_row.confrelid and target_attribute.attnum = keys.foreign_key
    where constraint_row.contype = 'f' and constraint_row.confrelid = 'public.users'::regclass and target_attribute.attname = 'id'
      and not (namespace.nspname = 'public' and (
        (relation.relname in ('user_departments', 'user_organizations') and attribute.attname = 'user_id')
        or (relation.relname = 'external_identities' and attribute.attname = 'canonical_user_id')
      ))
  loop
    execute format('select exists (select 1 from %I.%I where %I = any($1))',
      v_reference.schema_name, v_reference.table_name, v_reference.column_name)
      into v_has_reference using v_created_user_ids;
    if v_has_reference then raise exception 'directory has later changes: provisioned member is referenced' using errcode = '40001'; end if;
  end loop;
  if exists (select 1 from public.user_organizations where user_id = any(v_created_user_ids) and org_id <> p_system_org_id)
    or exists (select 1 from public.user_departments where user_id = any(v_created_user_ids) and org_id <> p_system_org_id)
    or exists (select 1 from public.external_identities where canonical_user_id = any(v_created_user_ids) and source_id <> v_plan.target_source_id) then
    raise exception 'directory has later changes: provisioned member has another association' using errcode = '40001';
  end if;

  select coalesce(array_agg((item->>'id')::uuid order by item->>'id'), array[]::uuid[])
    into v_before_department_ids
    from jsonb_array_elements(coalesce(v_before_state->'targetDepartments', '[]'::jsonb)) as item;
  select coalesce(array_agg((item->>'id')::uuid order by item->>'id'), array[]::uuid[])
    into v_before_identity_ids
    from jsonb_array_elements(coalesce(v_before_state->'targetIdentities', '[]'::jsonb)) as item;

  delete from public.user_departments
   where org_id = p_system_org_id and user_id = any(v_user_ids);
  for v_item in select value from jsonb_array_elements(coalesce(v_before_state->'memberships', '[]'::jsonb)) loop
    insert into public.user_departments(
      user_id, department_id, is_primary, joined_at, org_id, source
    ) values (
      (v_item->>'userId')::uuid,
      (v_item->>'departmentId')::uuid,
      (v_item->>'isPrimary')::boolean,
      (v_item->>'joinedAt')::timestamptz,
      (v_item->>'orgId')::uuid,
      coalesce(v_item->>'source', 'manual')
    );
  end loop;

  for v_item in select value from jsonb_array_elements(coalesce(v_before_state->'users', '[]'::jsonb)) loop
    v_user_id := (v_item->>'id')::uuid;
    update public.users
       set primary_dept_id = nullif(v_item->>'primaryDepartmentId', '')::uuid,
           status = nullif(v_item->>'status', ''),
           updated_at = (v_item->>'updatedAt')::timestamptz
     where id = v_user_id and org_id = p_system_org_id;
  end loop;

  delete from public.user_organizations membership
   where membership.org_id = p_system_org_id and membership.user_id = any(v_user_ids)
     and not exists (select 1 from jsonb_array_elements(v_before_state->'organizationMemberships') item
       where (item->>'userId')::uuid = membership.user_id);
  for v_item in select value from jsonb_array_elements(v_before_state->'organizationMemberships') loop
    update public.user_organizations set primary_department_id = nullif(v_item->>'primaryDepartmentId', '')::uuid,
      employment_status = v_item->>'employmentStatus'
     where org_id = p_system_org_id and user_id = (v_item->>'userId')::uuid;
  end loop;
  -- Clear new people's department FKs before restoring/removing the new department tree.
  update public.users set primary_dept_id = null where id = any(v_created_user_ids) and org_id = p_system_org_id;

  for v_item in select value from jsonb_array_elements(coalesce(v_before_state->'targetDepartments', '[]'::jsonb)) loop
    update public.departments
       set parent_id = nullif(v_item->>'parentId', '')::uuid,
           name = v_item->>'name',
           code = nullif(v_item->>'code', ''),
           path = nullif(v_item->>'path', ''),
           depth = (v_item->>'depth')::integer,
           external_id = nullif(v_item->>'externalId', ''),
           source = v_item->>'source',
           status = v_item->>'status',
           sort_order = (v_item->>'sortOrder')::integer,
           member_count = (v_item->>'memberCount')::integer,
           updated_at = (v_item->>'updatedAt')::timestamptz
     where id = (v_item->>'id')::uuid
       and org_id = p_system_org_id;
  end loop;
  update public.departments
     set parent_id = null
   where org_id = p_system_org_id
     and source = v_target_provider
     and not (id = any(v_before_department_ids));
  delete from public.departments
   where org_id = p_system_org_id
     and source = v_target_provider
     and not (id = any(v_before_department_ids));

  for v_item in select value from jsonb_array_elements(coalesce(v_before_state->'targetIdentities', '[]'::jsonb)) loop
    update public.external_identities
       set external_union_id = nullif(v_item->>'externalUnionId', ''),
           external_open_id = nullif(v_item->>'externalOpenId', ''),
           canonical_user_id = nullif(v_item->>'canonicalUserId', '')::uuid,
           match_status = v_item->>'matchStatus',
           match_method = v_item->>'matchMethod',
           match_confidence = (v_item->>'matchConfidence')::numeric,
           profile_snapshot = v_item->'profileSnapshot',
           observed_at = (v_item->>'observedAt')::timestamptz,
           updated_at = (v_item->>'updatedAt')::timestamptz
     where id = (v_item->>'id')::uuid
       and source_id = v_plan.target_source_id
       and system_org_id = p_system_org_id;
  end loop;
  delete from public.external_identities
   where system_org_id = p_system_org_id
     and source_id = v_plan.target_source_id
     and not (id = any(v_before_identity_ids));

  delete from public.users where id = any(v_created_user_ids) and org_id = p_system_org_id;

  update public.organization_sources set authority_scope = authority_scope - 'directory'
   where system_org_id = p_system_org_id and authority_scope->>'directory' in ('authoritative', 'true');
  for v_item in select value from jsonb_array_elements(coalesce(v_before_state->'sources', '[]'::jsonb)) loop
    update public.organization_sources
       set priority = (v_item->>'priority')::integer,
           status = v_item->>'status',
           authority_scope = coalesce(v_item->'authorityScope', '{}'::jsonb),
           sync_mode = v_item->>'syncMode',
           last_successful_sync_at = nullif(v_item->>'lastSuccessfulSyncAt', '')::timestamptz,
           last_error = nullif(v_item->>'lastError', ''),
           last_error_at = nullif(v_item->>'lastErrorAt', '')::timestamptz,
           updated_at = (v_item->>'updatedAt')::timestamptz
     where id = (v_item->>'id')::uuid
       and system_org_id = p_system_org_id;
  end loop;

  update public.organization_directory_cutover_runs
     set status = 'rolled_back', rolled_back_by = p_actor_id, rolled_back_at = v_now
   where id = v_run.id
  returning * into v_run;
  update public.organization_directory_cutover_plans
     set status = 'rolled_back', rolled_back_at = v_now
   where id = v_plan.id;

  return jsonb_build_object(
    'id', v_run.id, 'plan_id', v_run.plan_id, 'status', v_run.status,
    'target_source_id', v_run.target_source_id,
    'previous_primary_source_id', v_run.previous_primary_source_id,
    'department_count', v_run.department_count,
    'identity_count', v_run.identity_count,
    'member_count', v_run.member_count,
    'applied_at', v_run.applied_at, 'rolled_back_at', v_run.rolled_back_at
  );
end;
$$;

-- Enrich the existing organization aggregate from native membership tables in one read snapshot.
-- No employee is synthesized from a provider profile or external-identity row.
create or replace function public.get_org_admin_directory_payload_v1(p_org_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  with base as (select public.get_org_admin_payload_v1(p_org_id) as payload),
  identities as (
    select external_identity.*, count(*) over (partition by source_id, canonical_user_id) as mapping_count
    from public.external_identities external_identity
    where system_org_id = p_org_id and match_status = 'matched'
  )
  select payload || jsonb_build_object(
    'users', coalesce((select jsonb_agg(person.value || jsonb_build_object(
      'primary_dept_name', coalesce((select dept.name from public.departments dept
        where dept.org_id = p_org_id and dept.id = nullif(person.value->>'primary_dept_id', '')::uuid), '-'),
      'department_ids', coalesce((select jsonb_agg(link.department_id order by link.is_primary desc, link.department_id)
        from public.user_departments link join public.departments dept on dept.id = link.department_id and dept.org_id = p_org_id
        where link.org_id = p_org_id and link.user_id = (person.value->>'id')::uuid), '[]'::jsonb),
      'secondary_dept_names', coalesce((select jsonb_agg(dept.name order by dept.name)
        from public.user_departments link join public.departments dept on dept.id = link.department_id and dept.org_id = p_org_id
        where link.org_id = p_org_id and link.user_id = (person.value->>'id')::uuid and not link.is_primary), '[]'::jsonb),
      'directory_identity_id', identity.id,
      'directory_external_id', identity.external_user_id,
      'directory_source', source.provider,
      'directory_status', membership.employment_status,
      'directory_pending_account', coalesce(identity.profile_snapshot->>'provisionedMemberId' = person.value->>'id'
        and (person.value->>'login_enabled')::boolean = false, false)
    ) order by person.ordinality)
    from jsonb_array_elements(payload->'users') with ordinality person(value, ordinality)
    join public.user_organizations membership on membership.org_id = p_org_id and membership.user_id = (person.value->>'id')::uuid
    left join public.organization_sources source on source.system_org_id = p_org_id and source.authority_scope->>'directory' in ('authoritative', 'true')
    left join identities identity on identity.source_id = source.id
      and identity.canonical_user_id = membership.user_id and identity.mapping_count = 1
    ), '[]'::jsonb),
    'departments', coalesce((select jsonb_agg(jsonb_build_object(
      'id', dept.id, 'name', dept.name, 'code', dept.code, 'depth', dept.depth,
      'parent_id', dept.parent_id, 'parent_name', parent.name, 'member_count', dept.member_count,
      'source', dept.source, 'status', dept.status, 'external_id', dept.external_id,
      'leader_id', to_jsonb(dept)->>'leader_id', 'leader_name', leader.display_name
    ) order by dept.sort_order, dept.id)
    from public.departments dept
    left join public.departments parent on parent.id = dept.parent_id and parent.org_id = p_org_id
    left join public.users leader on leader.id = nullif(to_jsonb(dept)->>'leader_id', '')::uuid and leader.org_id = p_org_id
    where dept.org_id = p_org_id), '[]'::jsonb)
  ) from base;
$$;
revoke all on function public.get_org_admin_directory_payload_v1(uuid) from public, anon, authenticated;
grant execute on function public.get_org_admin_directory_payload_v1(uuid) to service_role;

revoke all on function private.organization_directory_state_v1(uuid,uuid,uuid[])
  from public, anon, authenticated;
revoke all on function private.organization_directory_state_matches_v1(uuid,uuid,jsonb)
  from public, anon, authenticated;
revoke all on function private.organization_source_revisions_match_v1(uuid,jsonb)
  from public, anon, authenticated;
revoke all on function public.store_organization_directory_cutover_plan_v1(uuid,uuid,uuid,uuid,text,text,jsonb,uuid,timestamptz)
  from public, anon, authenticated;
revoke all on function public.apply_organization_directory_cutover_v1(uuid,uuid,text,uuid,jsonb,uuid)
  from public, anon, authenticated;
revoke all on function public.rollback_organization_directory_cutover_v1(uuid,uuid,uuid)
  from public, anon, authenticated;
grant execute on function public.store_organization_directory_cutover_plan_v1(uuid,uuid,uuid,uuid,text,text,jsonb,uuid,timestamptz)
  to service_role;
grant execute on function public.apply_organization_directory_cutover_v1(uuid,uuid,text,uuid,jsonb,uuid)
  to service_role;
grant execute on function public.rollback_organization_directory_cutover_v1(uuid,uuid,uuid)
  to service_role;

comment on table public.organization_directory_cutover_plans is
  'Immutable, tenant-scoped directory diff plans bound to source and connection revisions.';
comment on table public.organization_directory_cutover_runs is
  'Atomic application and rollback audit with exact before/after directory states.';
comment on column public.user_departments.source is
  'Origin of a membership. Existing rows remain manual by default so a cutover cannot delete unclassified history.';
comment on function public.apply_organization_directory_cutover_v1(uuid,uuid,text,uuid,jsonb,uuid) is
  'Applies one complete conflict-free provider directory plan atomically; repeated calls return the same run.';
comment on function public.rollback_organization_directory_cutover_v1(uuid,uuid,uuid) is
  'Restores the exact pre-apply directory state and rejects rollback after any later directory or source change.';

commit;
